// Actual pinned primary algorithms; plain/passive output equality, no Go expectations.
const fs=require('fs'),vm=require('vm'),path=require('path'),crypto=require('crypto');const D=__dirname,B=process.argv[2],supplement=process.argv[3],out=process.argv[4];if(!B||!supplement||!out)throw Error('usage: node generate_macro_boundary.cjs PINNED_ASSETS NEWCOMMAND_3_2_2_JS NEW_EVIDENCE_DIRECTORY');if(fs.existsSync(out))throw Error('Evidence directory must be new');
if(process.env.NODE_OPTIONS)throw Error('normal Node required');const sha=x=>crypto.createHash('sha256').update(x).digest('hex');
const pins={'polyfills.js':'7fe1d048c78b0e09854c1259f7413868a51cc8f0c822489eb1ac36ae6c85ce01','mathjax.js':'cbbc1051a1f8abb1a181b6aa0fe927c020e3631ca630d19f52d9abb65b5ee869','setup.js':'a52cb0bbabfbd7796b9fedd793b9386c474e3123e788ee151cbe47ca1fa6e881'};
const assets=Object.fromEntries(Object.entries(pins).map(([n,h])=>{const b=fs.readFileSync(path.join(B,n));if(sha(b)!==h)throw Error(n);return[n,b.toString()]}));const supp=fs.readFileSync(supplement);if(sha(supp)!=='a41669a4ae924ab83cbc3d08f95ae90490a33cd649ed865e83675011b8708ab9')throw Error('Unpinned official 3.2.2 newcommand');
const body=fs.readFileSync(path.join(D,'macro_boundary_primary.js'),'utf8');fs.mkdirSync(out,{recursive:true});
function run(r,passive){const ctx=vm.createContext({console});vm.runInContext(assets['polyfills.js'],ctx);vm.runInContext(assets['mathjax.js'],ctx);if(r.profile==='official-newcommand-augmented')vm.runInContext(supp.toString(),ctx,{filename:'official-3.2.2/newcommand.js'});let setup=assets['setup.js'];if(r.profile==='official-newcommand-augmented'){if(!setup.includes("'physics'"))throw Error('setup anchor');setup=setup.replace("'physics'","'physics', 'newcommand'")};vm.runInContext(setup,ctx);ctx.request=r;ctx.passive=passive;return vm.runInContext(body,ctx,{filename:'primary-body.js',timeout:15000});}
let results=[];const noIDs=s=>({...s,parserID:undefined,stack:s.stack.map(x=>({...x,id:undefined}))}); const strip=r=>Array.isArray(r)?r.map(strip):Object.fromEntries(Object.entries(r).filter(([k])=>k!=='trace').map(([k,v])=>[k,(k==='before'||k==='after')?noIDs(v):v]));
const input=JSON.parse(fs.readFileSync(path.join(D,'macro_boundary_inputs.json')));const pub=input.public,helper=input.helpers.map(x=>({...x,type:'helper',profile:'fixed-packages'})),handlers=input.handlers;
function capture(r,group){let a,b;const prior=path.join(out,group+'-'+r.name+'.plain.json');try{if(fs.existsSync(prior)){a=JSON.parse(fs.readFileSync(prior));b=JSON.parse(fs.readFileSync(prior.replace('.plain.json','.passive.json')))}else{a=run(r,false);b=run(r,true)}}catch(e){fs.writeFileSync(path.join(out,group+'-'+r.name+'.failure.json'),JSON.stringify({error:String(e),stack:e.stack},null,2)+'\n');throw e}const eq=JSON.stringify(strip(a))===JSON.stringify(strip(b));if(!fs.existsSync(prior)){fs.writeFileSync(prior,JSON.stringify(a,null,2)+'\n');fs.writeFileSync(prior.replace('.plain.json','.passive.json'),JSON.stringify(b,null,2)+'\n');}if(!eq)throw Error('observer changed output '+r.name);if(a.svg!==undefined&&a.svg!==null)fs.writeFileSync(path.join(out,group+'-'+r.name+'.svg'),a.svg);results.push({group,name:r.name,profile:r.profile,plainPassiveExact:eq});}
for(const c of pub)capture(c,'public');for(const c of input.operatorname)capture(c,'operatorname');for(const c of helper)capture(c,'helper');for(const s of handlers){if(s.reuseDocument)capture({name:s.name,type:'sequence',cases:s.cases,profile:s.cases[0].profile},'handler');else for(const c of s.cases)capture({...c,name:s.name+'-'+c.name},'handler');}
fs.writeFileSync(path.join(out,'results.json'),JSON.stringify({node:process.version,execArgv:process.execArgv,pins,supplement:{sha256:sha(supp),size:supp.length},publicRecords:pub.length,helperScenarios:helper.length,handlerScenarios:handlers.length,observations:results},null,2)+'\n');console.log(JSON.stringify({public:pub.length,helpers:helper.length,handlerScenarios:handlers.length,observations:results.length,allPlainPassiveExact:true}));
